// S3 (shapeStage) workspace isolation for the 05 rebuild pipeline.
//
// Every mutable S3 working file must be scoped by project id + page + a per-run UUID:
// different projects can run the same page number concurrently, and the same page can be
// re-entered while a previous run is still alive. Nothing here may be shared between runs.
//
// The contrast-enhanced preview is the one intentionally shared artifact (same preview +
// background => same enhancement). It is generated by an external python tool, so it is
// written into the run's private directory first and published with atomic renames: the png
// first, the meta sidecar last. Readers treat a parseable meta as the commit marker, so a
// concurrent run can never consume a half-written png/meta pair.
import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import {execFile} from 'node:child_process';
import {promisify} from 'node:util';

const execFileAsync = promisify(execFile);

export const SHAPE_STAGE_WORKSPACE_VERSION = 1;

// Keep filesystem segments predictable; project ids / run ids come from internal state but a
// malformed value must never escape the geometry-records tree.
function segment(value, fallback) {
  const text = String(value ?? '').trim();
  return /^[A-Za-z0-9][A-Za-z0-9._-]{0,119}$/.test(text) ? text : fallback;
}

export function newShapeStageRunId() {
  return crypto.randomUUID();
}

// Page-N directory (shared only as a parent); every run gets its own run-<uuid> child.
export function shapeStagePageDirectory({env, project, index}) {
  const page = Number(index);
  const pageSegment = Number.isInteger(page) && page >= 0 ? 'page-' + (page + 1) : 'page-unknown';
  return path.join(env.data, segment(project?.id, 'unknown-project'), 'geometry-records',
    'shape-stage', pageSegment);
}

export function createShapeStageWorkspace({env, project, index, runId = newShapeStageRunId()}) {
  const pageDirectory = shapeStagePageDirectory({env, project, index});
  const safeRunId = segment(runId, 'run');
  const directory = path.join(pageDirectory, 'run-' + safeRunId);
  fs.mkdirSync(directory, {recursive: true});
  return {
    runId: safeRunId,
    pageDirectory,
    directory,
    specFile: path.join(directory, 'spec.json'),
    resultFile: path.join(directory, 'shape-result.json'),
    retryDirectory: path.join(directory, 'retry'),
    enhancedBackground: path.join(directory, 'enhanced-background.png'),
  };
}

// Include image content and the enhancement algorithm so edited files cannot reuse stale pixels.
export function enhancedPreviewCache({env, project, preview, background}) {
  const directory = path.join(env.data, segment(project?.id, 'unknown-project'),
    'geometry-records', 'enhance');
  const hash = crypto.createHash('sha256').update(String(preview) + '|' + String(background || ''));
  for (const file of [preview, background, path.join(env.root, 'tools', 'enhance_page.py')]) {
    if (file && fs.existsSync(file)) hash.update(fs.readFileSync(file));
  }
  const key = hash.digest('hex').slice(0, 16);
  const previewFile = path.join(directory, 'enhanced-' + key + '.png');
  return {directory, key, previewFile, metaFile: previewFile.replace(/\.png$/, '.json')};
}

// A published enhancement is only usable when both files exist and the meta sidecar parses.
// The meta is renamed into place last, so it also acts as the commit marker.
export function readEnhancement(cache) {
  try {
    if (!fs.statSync(cache.previewFile).isFile() || fs.statSync(cache.previewFile).size <= 0) {
      return null;
    }
    return JSON.parse(fs.readFileSync(cache.metaFile, 'utf8'));
  } catch {
    return null;
  }
}

export function enhancementTempPaths({cache, directory, runId}) {
  const file = path.join(directory, 'enhance-preview-' + cache.key + '-' + segment(runId, 'run') + '.png');
  return {previewFile: file, metaFile: file.replace(/\.png$/, '.json')};
}

// Rename is atomic inside the data directory. If the target is momentarily held open by a
// concurrent reader, retry after clearing it; readers then see "missing" (and regenerate)
// instead of a partially written file.
export function publishFileAtomic(sourceFile, targetFile) {
  fs.mkdirSync(path.dirname(targetFile), {recursive: true});
  for (let attempt = 0; attempt < 3; attempt += 1) {
    try {
      fs.renameSync(sourceFile, targetFile);
      return;
    } catch (error) {
      if (attempt === 2) throw error;
      try { fs.rmSync(targetFile, {force: true}); } catch {}
    }
  }
}

export function publishEnhancement({cache, temp}) {
  let meta;
  try {
    const size = fs.statSync(temp.previewFile).size;
    if (size <= 0) throw new Error('增强预览为空');
    meta = JSON.parse(fs.readFileSync(temp.metaFile, 'utf8'));
  } catch (error) {
    throw new Error('增强预览未完整生成：' + String(error && error.message || error).slice(0, 200));
  }
  publishFileAtomic(temp.previewFile, cache.previewFile);
  // Meta last: its presence is the commit marker for concurrent readers.
  publishFileAtomic(temp.metaFile, cache.metaFile);
  const published = readEnhancement(cache);
  if (!published) throw new Error('增强预览发布后不可读');
  return meta;
}

// Injection point for tests: production uses execFile; tests pass a fake that writes the
// expected tool output without launching python or touching user data.
export async function runShapeStageTool({python, script, args, exec, cwd, signal, timeout,executor=execFileAsync}) {
  if (typeof exec === 'function') return exec({python, script, args, cwd, signal, timeout});
  return executor(python, [script, ...args], {cwd, windowsHide: true, timeout, signal});
}
